+function updateProductView(filter) {
+  let visibleCount = 0;
+
+  productCards.forEach((card) => {
+    const isVisible = filter === "all" || card.dataset.category === filter;
+    card.hidden = !isVisible;
+
+    if (isVisible) {
+      visibleCount += 1;
+    }
+  });
+
+  const filterLabel = filter === "all" ? "featured products" : `${filter} products`;
+  productResults.textContent = `Showing ${visibleCount} ${filterLabel}.`;
