+  const days = Math.floor(safeDifference / (1000 * 60 * 60 * 24));
+  const hours = Math.floor((safeDifference / (1000 * 60 * 60)) % 24);
+  const minutes = Math.floor((safeDifference / (1000 * 60)) % 60);
