const productCards = document.querySelectorAll(".product-card");
const productResults = document.getElementById("product-results");
const bagButton = document.querySelector(".bag-button");
const bagCount = document.querySelector(".bag-count");
const bagStatus = document.getElementById("bag-status");
const addToBagButtons = document.querySelectorAll(".product-action");
const countdownValues = {
  days: document.querySelector('[data-unit="days"]'),
  hours: document.querySelector('[data-unit="hours"]'),
  minutes: document.querySelector('[data-unit="minutes"]'),
  seconds: document.querySelector('[data-unit="seconds"]'),
};
const timerStatus = document.getElementById("deal-timer-status");
const signupForm = document.querySelector(".signup-form");
const emailInput = document.getElementById("email-address");
const emailError = document.getElementById("email-error");
const formStatus = document.getElementById("form-status");

let bagItems = 0;

function updateProductView(filter) {
  let visibleCount = 0;

  productCards.forEach((card) => {
    const isVisible = filter === "all" || card.dataset.category === filter;
    card.hidden = !isVisible;

    if (isVisible) {
      visibleCount += 1;
    }
  });

  const filterLabel = filter === "all" ? "featured products" : `${filter} products`;
  productResults.textContent = `Showing ${visibleCount} ${filterLabel}.`;
}

filterButtons.forEach((button) => {
  button.addEventListener("click", () => {
    const selectedFilter = button.dataset.filter;

    filterButtons.forEach((control) => {
      const isSelected = control === button;
      control.classList.toggle("is-active", isSelected);
      control.setAttribute("aria-pressed", String(isSelected));
    });

    updateProductView(selectedFilter);
  });
});

addToBagButtons.forEach((button) => {
  button.addEventListener("click", () => {
    bagItems += 1;
    bagCount.textContent = String(bagItems);

    const productName = button.closest(".product-card")?.querySelector("h3")?.textContent || "item";
    bagStatus.textContent = `${productName} added to bag.`;
  });
});

const dealDeadline = new Date();
dealDeadline.setDate(dealDeadline.getDate() + 5);
dealDeadline.setHours(23, 59, 59, 999);

function padTime(value) {
  return String(value).padStart(2, "0");
}

function updateCountdown() {
  const difference = dealDeadline.getTime() - Date.now();
  const safeDifference = Math.max(difference, 0);

